def comprimir_repeticiones(texto: str) -> str:
    if not texto:
        return ""
    result = []
    i = 0
    n = len(texto)
    while i < n:
        ch = texto[i]
        j = i + 1
        while j < n and texto[j] == ch:
            j += 1
        count = j - i
        result.append(f"{ch}{count}")
        i = j
    return "".join(result)

def flatten(obj):
    if isinstance(obj, (list, tuple)):
        for item in obj:
            yield from flatten(item)
    else:
        yield obj

def aplanar(datos: list) -> list:
    result = []
    for item in datos:
        result.extend(flatten(item))
    return result

def promedio_movil(valores: list[float], ventana: int) -> list[float]:
    if not valores or ventana <= 0 or len(valores) < ventana:
        return []
    resultado = []
    for i in range(len(valores) - ventana + 1):
        resultado.append(sum(valores[i:i+ventana]) / ventana)
    return resultado

from collections import OrderedDict


class CacheLRU:
    def __init__(self, capacidad: int):
        if capacidad < 0:
            raise ValueError("Capacidad no puede ser negativa")
        self.capacidad = capacidad
        self._datos = OrderedDict()

    def get(self, clave):
        if clave in self._datos:
            value = self._datos[clave]
            self._datos.move_to_end(clave, last=True)
            return value
        else:
            return None

    def put(self, clave, valor):
        if self.capacidad == 0:
            return
        if clave in self._datos:
            self._datos[clave] = valor
            self._datos.move_to_end(clave, last=True)
        else:
            if len(self._datos) >= self.capacidad:
                self._datos.popitem(last=False)
            self._datos[clave] = valor

    def __len__(self):
        return len(self._datos)
